typedef struct { pthread_mutex_t lock; long balance; } account_t;

pthread_mutex_t *account_lock(account_t *a) { return &a->lock; }  /* published */

void transfer(account_t *from, account_t *to, long amount) {
    pthread_mutex_lock(account_lock(from));      /* fixed order: from, then to */
    pthread_mutex_lock(account_lock(to));
    from->balance -= amount; to->balance += amount;  /* one critical section */
    pthread_mutex_unlock(account_lock(to));
    pthread_mutex_unlock(account_lock(from));
}
